'use client';
import { useState } from 'react';
import { Radio, Send } from 'lucide-react';
export default function SignalsManager() { const [sent, setSent] = useState(false); return <div className="p-5 md:p-8 lg:p-10"><p className="text-xs font-bold uppercase tracking-[.25em] text-cyan">Market operations</p><h1 className="mt-3 text-3xl font-black">AI Signals</h1><div className="mt-8 grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><div className="rounded-2xl border border-white/10 bg-card p-6"><h2 className="font-bold">Broadcast a signal</h2><div className="mt-5 grid gap-4"><select className="rounded-xl border border-white/10 bg-ink p-3"><option>Forex</option><option>Crypto</option><option>Stocks</option></select><input className="rounded-xl border border-white/10 bg-ink p-3" placeholder="Symbol e.g. EURUSD" /><select className="rounded-xl border border-white/10 bg-ink p-3"><option>BUY</option><option>SELL</option></select><div className="grid grid-cols-2 gap-3"><input className="rounded-xl border border-white/10 bg-ink p-3" placeholder="Entry" /><input className="rounded-xl border border-white/10 bg-ink p-3" placeholder="Take profit" /></div><input className="rounded-xl border border-white/10 bg-ink p-3" placeholder="Stop loss" /><textarea className="min-h-24 rounded-xl border border-white/10 bg-ink p-3" placeholder="Signal rationale" /><button onClick={() => setSent(true)} className="flex items-center justify-center gap-2 rounded-xl bg-cyan py-3 font-bold text-ink"><Send className="h-4 w-4" /> {sent ? 'Signal broadcast' : 'Publish signal'}</button></div></div><div className="rounded-2xl border border-white/10 bg-card p-6"><div className="flex items-center justify-between"><h2 className="font-bold">Recent signals</h2><span className="flex items-center gap-2 text-xs text-green-400"><span className="h-2 w-2 rounded-full bg-green-400" /> Live feed</span></div>{[['EURUSD','BUY','92%','2m ago'],['BTCUSDT','BUY','88%','18m ago'],['NVDA','SELL','76%','1h ago'],['XAUUSD','BUY','84%','2h ago']].map(([symbol,direction,confidence,time]) => <div className="mt-4 flex items-center justify-between rounded-xl border border-white/10 p-4" key={symbol}><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-lg bg-cyan/10"><Radio className="h-4 w-4 text-cyan" /></span><div><p className="font-semibold">{symbol}</p><p className="text-xs text-muted">{time}</p></div></div><div className="text-right"><p className={direction === 'BUY' ? 'text-green-400' : 'text-red-400'}>{direction}</p><p className="text-xs text-muted">{confidence} conviction</p></div></div>)}</div></div></div>; }